import type { NextConfig } from "next";

// Content-Security-Policy: moderate, integration-aware. Uses 'unsafe-inline'
// (no nonce infra yet) but still adds real protections — object-src none,
// base-uri/form-action self, frame-ancestors none, and script/frame allowlists
// for Stripe + analytics. connect-src is permissive to keep the console (wss)
// and API integrations working.
const csp = [
  "default-src 'self'",
  "base-uri 'self'",
  "object-src 'none'",
  "frame-ancestors 'none'",
  "form-action 'self'",
  "img-src 'self' data: blob: https:",
  "font-src 'self' data:",
  "style-src 'self' 'unsafe-inline'",
  // PayPal's JS SDK (loaded by @paypal/react-paypal-js on the embedded Payment
  // step) both executes a script from paypal.com/paypalobjects.com AND opens an
  // in-page iframe from the same origins for the button + approval flow — found
  // by actually loading the page in a real browser (Playwright) during the
  // embedded-payment-UI build, where the button silently failed to render with
  // nothing but a CSP violation in the console. Sandbox's domain is included too
  // so a `PAYPAL_MODE=sandbox` testing session isn't the ONE environment this
  // never got exercised in.
  "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://plausible.io https://*.googletagmanager.com https://www.google-analytics.com https://js.stripe.com https://www.paypal.com https://www.paypalobjects.com https://www.sandbox.paypal.com",
  "connect-src 'self' https: wss:",
  // blob: lets the webmail render an email body in a sandboxed blob:-URL iframe
  // (a `srcdoc` frame loads as about:srcdoc, which this frame-src refuses). The
  // frame stays fully sandboxed and inherits the rest of this CSP.
  "frame-src 'self' blob: https://js.stripe.com https://hooks.stripe.com https://www.paypal.com https://www.sandbox.paypal.com",
  "worker-src 'self' blob:",
  "manifest-src 'self'",
  "upgrade-insecure-requests",
].join("; ");

const securityHeaders = [
  { key: "Content-Security-Policy", value: csp },
  { key: "X-Content-Type-Options", value: "nosniff" },
  // NOTE: X-Frame-Options is intentionally NOT set here — nginx already sends it,
  // and two conflicting values (DENY vs SAMEORIGIN) is undefined behaviour.
  // CSP `frame-ancestors 'none'` above is the authoritative, stricter control.
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  // microphone=(self): the Matrix build console offers voice-to-text (Web Speech
  // API), which the browser gates on the microphone permission policy. A bare
  // microphone=() disables the mic for the whole origin, so the mic button did
  // nothing at all. (self) grants it to our own pages only — third-party frames
  // still can't use it. camera/geolocation stay fully disabled (never used).
  { key: "Permissions-Policy", value: "camera=(), microphone=(self), geolocation=(), interest-cohort=()" },
  { key: "X-DNS-Prefetch-Control", value: "on" },
];

const nextConfig: NextConfig = {
  output: "standalone",
  // ssh2 (and its SFTP wrapper) ship an OPTIONAL native addon (sshcrypto.node).
  // When the toolchain is present at install time npm builds that binary, and
  // webpack then fails trying to parse it into the server bundle. These are
  // server-only modules, so mark them external — Next require()s them at runtime
  // instead of bundling, which is the correct treatment for a native addon and
  // is behaviour-neutral (falls back to ssh2's pure-JS crypto when unbuilt).
  serverExternalPackages: ["@prisma/client", "bcryptjs", "ssh2", "ssh2-sftp-client", "geoip-lite"],
  experimental: {
    // Webmail attachments travel through a Server Action as base64, and Next's
    // default Server Action body limit is 1 MB. Base64 inflates by ~4/3, so
    // anything over roughly 700 KB was rejected by the framework before our
    // handler ever ran — while both the composer
    // (components/customer/mail/Composer.tsx) and the server
    // (lib/actions-mail.ts MAX_ATTACHMENTS_TOTAL_BYTES) advertised 20 MB.
    // Customers attached a 2 MB PDF and the mail silently failed to send.
    // 20 MB of files encodes to ~26.7 MB; 30 MB leaves headroom for the rest of
    // the payload (recipients, subject, HTML body). lib/actions-mail.ts still
    // enforces the real 20 MB cap, with a message the customer can act on.
    serverActions: { bodySizeLimit: "30mb" },
  },
  async headers() {
    // Static image assets under /public default to `max-age=0` (revalidate on
    // every request) — fine for an app served from a CDN edge, but this origin
    // has no CDN in front of it (confirmed: nxeon.cloud resolves straight to
    // the single origin IP, no proxy). Every visitor everywhere round-trips to
    // this one box for the logo on every single page load. Confirmed live from
    // this host: 20ms — but a customer's round-trip from another continent is
    // a different story, and a multi-region browsing check surfaced the logo
    // failing to render in some locations, consistent with a slow/uncached
    // image request timing out on a long-haul connection. These filenames only
    // change via a deploy (new build = new deploy = fine to cache hard);
    // `immutable` tells the browser to skip revalidation entirely for the
    // whole max-age window instead of asking the origin on every load.
    const longCache = [{ key: "Cache-Control", value: "public, max-age=31536000, immutable" }];
    return [
      { source: "/:path*", headers: securityHeaders },
      { source: "/logo.png", headers: longCache },
      { source: "/nx-mark.png", headers: longCache },
      { source: "/games/art/:path*", headers: longCache },
      { source: "/logos/:path*", headers: longCache },
    ];
  },
  async redirects() {
    // The RevSports venture page was retired. 301 to home so any indexed URL or
    // stray inbound link lands somewhere real instead of 404-ing.
    return [{ source: "/revsports", destination: "/", permanent: true }];
  },
};

export default nextConfig;

