import { db } from "@/lib/db";
import type { BlogPost } from "@prisma/client";

export const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

/* ----------------------------------------------------------------------------
 * Fetch helpers
 * ------------------------------------------------------------------------- */

/** Published posts, newest first — for the public blog index. */
export function getPublishedPosts(): Promise<BlogPost[]> {
  return db.blogPost.findMany({
    where: { published: true },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
  });
}

/** A single published post by slug, or null (drives notFound() on the page). */
export function getPublishedPost(slug: string): Promise<BlogPost | null> {
  return db.blogPost.findFirst({ where: { slug, published: true } });
}

/**
 * Full-text-ish search over published posts. Case-insensitive `contains` across
 * title / excerpt / body, plus an exact tag match. Empty query falls back to the
 * normal newest-first listing. Runs server-side so results are crawlable.
 */
export function searchPublishedPosts(q: string): Promise<BlogPost[]> {
  const query = q.trim();
  if (!query) return getPublishedPosts();
  return db.blogPost.findMany({
    where: {
      published: true,
      OR: [
        { title: { contains: query, mode: "insensitive" } },
        { excerpt: { contains: query, mode: "insensitive" } },
        { body: { contains: query, mode: "insensitive" } },
        { category: { contains: query, mode: "insensitive" } },
        { tags: { has: query.toLowerCase() } },
      ],
    },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
  });
}

/**
 * Up to `limit` other published posts related to `post` — same category first,
 * back-filled with the newest posts so the block is never short. The current
 * post is always excluded. Drives the "Related articles" internal-linking block
 * on the post page (the biggest lever for getting thin/orphaned posts indexed).
 */
export async function getRelatedPosts(post: BlogPost, limit = 3): Promise<BlogPost[]> {
  const sameCategory = await db.blogPost.findMany({
    where: { published: true, category: post.category, id: { not: post.id } },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
    take: limit,
  });
  if (sameCategory.length >= limit) return sameCategory;

  // Back-fill with the newest posts, skipping anything already picked.
  const have = new Set([post.id, ...sameCategory.map((p) => p.id)]);
  const recent = await db.blogPost.findMany({
    where: { published: true, id: { notIn: [...have] } },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
    take: limit - sameCategory.length,
  });
  return [...sameCategory, ...recent];
}

/**
 * Map a post to the single most relevant product page so every article funnels
 * to a money page (internal-linking + conversion). Matches the post's category,
 * tags and title against product keywords; falls back to the pricing page.
 */
export function productLinkForPost(post: BlogPost): { label: string; href: string; blurb: string } {
  const hay = `${post.category} ${post.tags.join(" ")} ${post.title}`.toLowerCase();
  const has = (...ks: string[]) => ks.some((k) => hay.includes(k));

  if (has("minecraft", "rust", "game", "valheim", "palworld", "ark", "fivem", "server hosting"))
    return {

