// Visitor-analytics daily rollup. Summarises the raw `Visit` log into one
// `VisitorDaily` row per UTC day so the admin audience dashboard's trend series
// and long-range history stay cheap as the visit log grows. Best-effort: one bad
// day never aborts the sweep, and nothing here writes to Visit.
import { db } from "../lib/db";
import { computeVisitorDay } from "../lib/analytics";

/** How many trailing UTC days to (re)roll each sweep. A small window so late
 *  close-beacons (dwell time) and just-past-midnight hits still land in the
 *  right day without rescanning all of history every pass. */
const ROLL_DAYS = 3;

function utcDayStart(offsetDays: number): Date {
  const now = new Date();
  const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  d.setUTCDate(d.getUTCDate() - offsetDays);
  return d;
}

/**
 * Roll the last few UTC days into VisitorDaily. Each day also counts signups
 * (accounts created that day) and how many of those accounts deployed a real
 * server, so the funnel has durable per-day history too.
 */
export async function visitorRollupSweep(): Promise<void> {
  for (let i = 0; i < ROLL_DAYS; i++) {
    const dayStart = utcDayStart(i);
    const dayEnd = new Date(dayStart.getTime() + 86_400_000 - 1);
    try {
      const m = await computeVisitorDay(dayStart, dayEnd);

      // Per-day funnel: signups that day + how many deployed a server.
      const signupUsers = await db.user.findMany({
        where: { createdAt: { gte: dayStart, lte: dayEnd } },
        select: { id: true },
        take: 20_000,
      });
      const signupIds = signupUsers.map((u) => u.id);
      let deployed = 0;
      if (signupIds.length > 0) {
        const rows = await db.server.findMany({
          where: {
            userId: { in: signupIds },
            status: { in: ["RUNNING", "STOPPED", "SUSPENDED", "REINSTALLING", "DELETING"] },
          },
          distinct: ["userId"],
          select: { userId: true },
        });
        deployed = rows.length;
      }

      // Recover total session dwell for the day (computeVisitorDay returns the
      // average; multiply back so the stored total stays authoritative).
      const totalSessionMs = BigInt(m.avgSessionMs) * BigInt(m.sessions);

      const data = {
        pageviews: m.pageviews,
        sessions: m.sessions,
        uniqueVisitors: m.uniqueVisitors,
        newVisitors: m.newVisitors,
        returningVisitors: m.returningVisitors,
        bounces: 0, // reserved; bounce rate is computed live on the dashboard
        totalSessionMs,
        signups: signupIds.length,
        deployed,
      };

      await db.visitorDaily.upsert({
        where: { date: dayStart },
        create: { date: dayStart, ...data },
        update: data,
      });
    } catch (e) {
      console.error("[analytics] visitor rollup error", dayStart.toISOString().slice(0, 10), e);
    }
  }
}

