// SEO consolidation + orphan-fix for DB-backed BlogPost rows.
// ---------------------------------------------------------------------------
// WHY THIS IS A SCRIPT (not applied in staging): the affected posts live only
// in the PRODUCTION `nxeon` database (the 200-post SEO batch), not in
// `nxeon_staging`. The code-side companions (301s in next.config.ts, the
// dropped CS2 link, the marketing-page inbound links, the palworld nudges) are
// already applied in the staging tree. This script applies the DB-side half.
//
// SAFETY:
//   * DRY-RUN by default. Prints every change. Pass `--apply` to write.
//   * Refuses to run unless NXEON_DB_TARGET matches the database in DATABASE_URL
//     (same control as scripts/db-target-guard.ts — a symlinked node_modules can
//     silently resolve .env to the wrong tree).
//   * Body edits only ever APPEND, each guarded by a unique HTML-comment marker,
//     so re-running is idempotent and never duplicates or overwrites content.
//   * Link repointing is a targeted string replace (no-op if the link is absent).
//   * Never deletes a row; the three duplicates are set published=false only.
//   * No-ops cleanly on any slug that isn't present.
//
// RUN (from the tree whose .env points at the prod DB, i.e. /opt/nxeon):
//   NXEON_DB_TARGET=nxeon node scripts/seo-blog-consolidation.mjs            # dry run
//   NXEON_DB_TARGET=nxeon node scripts/seo-blog-consolidation.mjs --apply    # write
// ---------------------------------------------------------------------------
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();
const APPLY = process.argv.includes("--apply");

/* -- db-target guard (inline; mirrors scripts/db-target-guard.ts) ---------- */
function dbNameFromUrl(url) {
  if (!url) return null;
  try {
    const u = new URL(url);
    if (!/^postgres(ql)?:$/.test(u.protocol)) return null;
    const raw = decodeURIComponent(u.pathname.replace(/^\//, ""));
    return raw || null;
  } catch {
    return null;
  }
}
const dbName = dbNameFromUrl(process.env.DATABASE_URL);
const target = process.env.NXEON_DB_TARGET;
if (!dbName) {
  console.error("Refusing to run: could not read a database name from DATABASE_URL.");
  process.exit(1);
}
if (target !== dbName) {
  console.error(
    `Refusing to run: NXEON_DB_TARGET=${JSON.stringify(target)} does not match the ` +
      `database in DATABASE_URL (${JSON.stringify(dbName)}).\n` +
      `Re-run with:  NXEON_DB_TARGET=${dbName} node scripts/seo-blog-consolidation.mjs${APPLY ? " --apply" : ""}`
  );
  process.exit(1);
}

/* -- canonical / redirected slugs ----------------------------------------- */
const CANON_SHARED = "why-a-vps-beats-shared-hosting-for-a-growing-site";
const CANON_CS2 = "how-to-set-up-a-counter-strike-2-dedicated-server";
const REDIRECTED_SHARED = [
  "shared-hosting-vs-vps-for-a-growing-site",
  "shared-hosting-vs-vps-which-to-choose",
  "vps-vs-shared-hosting-which-do-you-need",
];
const REDIRECTED_CS2 = "how-to-set-up-a-cs2-server";
const ORPHAN = "vps-vs-dedicated-game-server-hosting";

// Repoint map: any body link to a redirected slug -> its canonical slug.
const REPOINT = new Map([
  ...REDIRECTED_SHARED.map((s) => [s, CANON_SHARED]),
  [REDIRECTED_CS2, CANON_CS2],
]);

/* -- helpers -------------------------------------------------------------- */
let changes = 0;
async function getExistingSlugs(candidates) {
  const rows = await db.blogPost.findMany({
    where: { slug: { in: candidates } },
    select: { slug: true },
  });
  return new Set(rows.map((r) => r.slug));
}
async function appendGuarded(slug, marker, block, label) {
  const post = await db.blogPost.findUnique({ where: { slug }, select: { id: true, body: true } });
  if (!post) return console.log(`  skip (missing): ${slug} — ${label}`);
  if (post.body.includes(marker)) return console.log(`  already applied: ${slug} — ${label}`);
  const body = `${post.body.trimEnd()}\n\n${marker}\n${block.trim()}\n`;
  changes++;
  console.log(`  APPEND ${label} -> ${slug}`);
  if (APPLY) await db.blogPost.update({ where: { id: post.id }, data: { body } });
}

async function main() {
  console.log(`DB=${dbName}  mode=${APPLY ? "APPLY (writing)" : "DRY-RUN (no writes)"}\n`);

  // 1a. Unpublish the three shared-vs-VPS duplicates (leave rows intact so the
  //     301s in next.config.ts have somewhere to fire from; unpublished =>
  //     dropped from app/sitemap.ts, which filters where published:true).
  console.log("[1] Unpublish shared-vs-VPS duplicates");
  for (const slug of REDIRECTED_SHARED) {
    const p = await db.blogPost.findUnique({ where: { slug }, select: { id: true, published: true } });
    if (!p) { console.log(`  skip (missing): ${slug}`); continue; }
    if (!p.published) { console.log(`  already unpublished: ${slug}`); continue; }
    changes++;
    console.log(`  UNPUBLISH ${slug}`);
    if (APPLY) await db.blogPost.update({ where: { id: p.id }, data: { published: false } });
  }

  // 1b. Repoint in-body links from redirected slugs to their canonical target,
  //     across every post (so no live post links into a 301).
  console.log("\n[1] Repoint in-body links to canonical slugs");
  const all = await db.blogPost.findMany({ select: { id: true, slug: true, body: true } });
  for (const p of all) {
    let body = p.body;
    for (const [from, to] of REPOINT) {
      body = body.split(`/blog/${from}`).join(`/blog/${to}`);
    }
    if (body !== p.body) {
      changes++;
      console.log(`  REPOINT links in ${p.slug}`);
      if (APPLY) await db.blogPost.update({ where: { id: p.id }, data: { body } });
    }
  }

  // 2. Fix the orphan post: append OUT links, a panel-vs-VPS table, and a FAQ.
  //    The Minecraft setup-guide slug is discovered from a candidate list so
  //    this stays correct whatever the batch named it.
  console.log("\n[2] Orphan post out-links + table + FAQ");
  const mcCandidates = [
    "how-to-set-up-a-minecraft-server",
    "how-to-set-up-a-minecraft-server-on-a-vps",
    "how-to-set-up-a-minecraft-server-on-linux",
    "how-to-set-up-a-minecraft-bedrock-dedicated-server",
  ];
  const mcSlug = [...(await getExistingSlugs(mcCandidates))][0] ?? "how-to-set-up-a-minecraft-bedrock-dedicated-server";
  const orphanBlock = `## Game panel vs a VPS: which should you use?

If you just want a server online fast with a friendly dashboard, a managed [game server](/game-servers) with a control panel is the quickest path — one click to deploy, a live console, a player list and a mod manager, no Linux required. If you want total control — custom mods, several games on one box, or other software running alongside — a VPS gives you root access to the raw hardware.

Either way, size the box correctly first: see [game server specs explained: CPU, RAM and bandwidth](/blog/game-server-specs-explained-cpu-ram-and-bandwidth). Ready to build one yourself? Our step-by-step guides cover [Counter-Strike 2](/blog/${CANON_CS2}) and [Minecraft](/blog/${mcSlug}).

| | Game panel | VPS |
| --- | --- | --- |
| Setup | One-click, minutes | Manual (SteamCMD, ports, updates) |
| Control | Panel + full file access | Full root access |
| Best for | A single game, fast | Custom stacks, multiple games |
| Skill needed | None | Comfortable with Linux |
| Updates & restarts | Automated for you | You manage (or script) them |

### FAQ

**Is a dedicated game server the same as a VPS?**
Not quite. A dedicated game server here means a managed instance behind a game control panel — the platform installs the game, applies updates and handles restarts. A VPS is a raw virtual machine with root access that you configure yourself. Both run on real, dedicated CPU, RAM and NVMe.

**Which is cheaper?**
For a single game, a panel-managed [game server](/game-servers) is usually the better value once you count your own time. A VPS can cost less per GB of RAM if you run several servers on one box and don't mind the administration.`;
  await appendGuarded(ORPHAN, "<!-- seo-orphan-fix -->", orphanBlock, "orphan out-links + table + FAQ");

  // 2b. Inbound links to the orphan from a couple of "how to set up a [game]
  //     server" posts, anchored ~"game panel vs a VPS".
  console.log("\n[2] Inbound links to the orphan from setup guides");
  const inboundBlock = `Not sure whether to use a managed panel or a raw box? See our guide on [game panel vs a VPS](/blog/${ORPHAN}).`;
  for (const slug of [CANON_CS2, "how-to-set-up-a-palworld-dedicated-server-on-a-vps"]) {
    await appendGuarded(slug, "<!-- seo-orphan-inbound -->", inboundBlock, "inbound link to orphan");
  }

  // 4. Striking-distance FAQ on the small-business post.
  console.log("\n[4] best-vps-for-a-small-business-website FAQ");
  const smbBlock = `### Do I need a VPS for a business?

Not always — a light brochure site can start on shared hosting. But once your site carries real traffic, runs a store, or needs custom software, its own email, or reliability you can count on, a VPS pays off: dedicated CPU and RAM, root access, your own IP address, and no noisy neighbours slowing you down at the worst possible moment. It's the natural next step the day shared hosting starts to hold your business back.`;
  await appendGuarded("best-vps-for-a-small-business-website", "<!-- seo-smb-faq -->", smbBlock, "SMB FAQ");

  // 4b. Internal links out of the what-is-a-vps pillar to related cluster posts.
  console.log("\n[4] what-is-a-vps internal links");
  const clusterCandidates = [
    [CANON_SHARED, "Why a VPS beats shared hosting for a growing site"],
    ["best-vps-for-wordpress", "Best VPS for WordPress"],
    ["best-vps-for-a-small-business-website", "Best VPS for a small business website"],
    ["how-to-point-a-domain-at-your-vps", "How to point a domain at your VPS"],
    ["game-server-specs-explained-cpu-ram-and-bandwidth", "Game server specs explained: CPU, RAM and bandwidth"],
    [ORPHAN, "VPS vs dedicated game server hosting"],
    ["cheap-vps-vs-expensive-vps-what-actually-differs", "Cheap vs expensive VPS: what actually differs"],
    ["how-much-ram-and-cpu-does-a-vps-need", "How much RAM and CPU does a VPS need"],
  ];
  const existing = await getExistingSlugs(clusterCandidates.map(([s]) => s));
  const links = clusterCandidates.filter(([s]) => existing.has(s)).slice(0, 8);
  if (links.length >= 5) {
    const block = `## Keep learning about VPS\n\n${links.map(([s, label]) => `- [${label}](/blog/${s})`).join("\n")}`;
    await appendGuarded("what-is-a-vps", "<!-- seo-whatisavps-links -->", block, `${links.length} cluster links`);
  } else {
    console.log(`  skip: only ${links.length} cluster targets exist (need >=5) — widen the candidate list`);
  }

  console.log(`\n${APPLY ? "Applied" : "Would apply"} ${changes} change(s).`);
  await db.$disconnect();
}
main().catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });
